 "content": "from collections import Counter


def _continuation_period(row, end, background):
    """Find a short exact periodic suffix ending at the last foreground cell."""
    for period in range(1, end + 1):
        start = end - period
        if start < 0:
            continue
        # Require at least one full period plus an overlap to establish phase.
        overlap = 0
        i = end
        while i - period >= 0 and row[i] == row[i - period]:
            overlap += 1
            i -= 1
        if overlap >= 1:
            # A solid terminal run is period 1; otherwise use the shortest
            # evidenced repeated suffix (e.g. a 3-cell motif with one overlap).
            return period
    return 1


def transform(grid):
    """Continue right-edge row motifs in each separated foreground band."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
