        while r < h and all(v == background for v in grid[r]):
            r += 1
        if r == h:
            break
        start = r
        while r < h and any(v != background for v in grid[r]):
            r += 1
        bands.append((start, r))

    for top, bottom in bands:
        ends = {}
        for rr in range(top, bottom):
            inds = [c for c, v in enumerate(grid[rr]) if v != background]
            if inds:
                ends[rr] = inds[-1]
        if not ends:
